SELECT customer_id, tenant_id, name, email, phone, country_code, platform,
       store_id, total_orders, total_spent, last_order_at, tags, created_at, updated_at
FROM crm_customer WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}

